document.addEventListener("DOMContentLoaded",function(){let o=["Um passo por dia já é progresso.","Você está indo melhor do que imagina.","Continue. Seu futuro agradece.","Não desista. Grandes coisas levam tempo.","Respira. Você é capaz.","Seu esforço de hoje constrói seu amanhã.","Confie no processo.","Você não chegou até aqui por acaso."];document.getElementById("form-frase").addEventListener("submit",function(e){e.preventDefault();e=Math.floor(Math.random()*o.length),e=o[e];document.getElementById("frase-texto").innerText=e,document.querySelector(".resultado").style.display="block"})});